import json


def validate(obj, schema, path="$"):
    errs = []
    t = schema.get("type")
    if t == "object":
        if not isinstance(obj, dict):
            return [path + ": not an object"]
        for k in schema.get("required", []):
            if k not in obj:
                errs.append(path + "." + k + ": required missing")
        for k, sub in (schema.get("properties") or {}).items():
            if k in obj:
                errs += validate(obj[k], sub, path + "." + k)
    elif t == "integer":
        if not isinstance(obj, int) or isinstance(obj, bool):
            return [path + ": not an integer"]
        if "minimum" in schema and obj < schema["minimum"]:
            errs.append(path + ": below minimum")
        if "maximum" in schema and obj > schema["maximum"]:
            errs.append(path + ": above maximum")
    elif t == "string":
        if not isinstance(obj, str):
            return [path + ": not a string"]
        if "minLength" in schema and len(obj) < schema["minLength"]:
            errs.append(path + ": too short")
        if "maxLength" in schema and len(obj) > schema["maxLength"]:
            errs.append(path + ": too long")
        if "enum" in schema and obj not in schema["enum"]:
            errs.append(path + ": not in enum")
    return errs


SCHEMA = {
    "type": "object",
    "required": ["city", "temp_c", "unit"],
    "properties": {
        "city": {"type": "string", "minLength": 1},
        "temp_c": {"type": "integer", "minimum": -90, "maximum": 60},
        "unit": {"type": "string", "enum": ["C", "F"]},
    },
}

CANDS = [
    '{"city": "BJ", "temp_c": 24, "unit": "C"}',
    '{"city": "SH", "temp_c": 26}',
    '{"city": "", "temp_c": 20, "unit": "C"}',
    '{"city": "GZ", "temp_c": 200, "unit": "C"}',
    '{"city": "SZ", "temp_c": 30, "unit": "K"}',
    '{"city": "WH", "temp_c": 22.5, "unit": "C"}',
]

ok = 0
for i, raw in enumerate(CANDS):
    try:
        obj = json.loads(raw)
    except Exception as e:
        print("#%d JSON 解析失败: %s" % (i + 1, type(e).__name__))
        continue
    errs = validate(obj, SCHEMA)
    if errs:
        print("#%d INVALID: %s" % (i + 1, "; ".join(errs)))
    else:
        ok += 1
        print("#%d OK" % (i + 1))

print("pass rate: %d/%d = %.1f%%" % (ok, len(CANDS), 100.0 * ok / len(CANDS)))
